compile.workshop:
variables {
    global:
        0: g
}

rule ("terminal conditionals") {
    event {
        Ongoing - Each Player;
        All;
        All;
    }
    conditions {
        Global.g > 0;
    }
    actions {
        Abort If(Compare(Global.g, ==, 1));
        Loop If Condition Is True;
        Abort If Condition Is False;
        Abort;
        Set Global Variable(g, 2);
        Loop If(Compare(Global.g, ==, 3));
        Abort;
    }
}

